+using Spectre.Console.Cli;
+
+namespace JobTrack.Cli;
+
+public abstract class JobTrackReadCommand<TSettings> : AsyncCommand<TSettings>
+    where TSettings : CommandSettings
+{
+    private readonly IJobTrackApiClient _client;
+    private readonly IConsoleWriter _console;
+
+    protected JobTrackReadCommand(IJobTrackApiClient client, IConsoleWriter console)
+    {
+        _client = client;
+        _console = console;
+    }
+
+    protected async Task<int> GetAndWriteAsync(
+        string commandName,
+        Func<IJobTrackApiClient, CancellationToken, Task<IJobTrackReadData>> readData,
+        OutputFormat output,
+        CancellationToken cancellationToken = default)
+    {
+        IJobTrackReadData data;
+        try
+        {
+            data = await readData(_client, cancellationToken);
+        }
+        catch (JobTrackApiException ex)
+        {
+            _console.ErrorLine($"jt {commandName}: {ex.Message}");
+            var details = OutputFormatter.FormatApiData(ex.Details, OutputFormat.Table);
+            if (!string.IsNullOrWhiteSpace(details))
+            {
+                _console.ErrorLine(details);
+            }
+
+            return 1;
+        }
+        catch (JobTrackConfigurationException ex)
+        {
+            _console.ErrorLine($"jt {commandName}: {ex.Message}");
+            return 1;
+        }
+        catch (JobTrackApiResponseException ex)
+        {
+            _console.ErrorLine($"jt {commandName}: {ex.Message}");
+            return 1;
+        }
+        catch (JobTrackApiRequestException ex)
+        {
+            _console.ErrorLine($"jt {commandName}: request failed: {ex.Message}");
+            return 1;
+        }
+        catch (OperationCanceledException ex)
+        {
+            _console.ErrorLine($"jt {commandName}: request canceled or timed out: {ex.Message}");
+            return 1;
+        }
+
+        var text = OutputFormatter.FormatApiData(data, output);
+        if (!string.IsNullOrEmpty(text))
+        {
+            _console.WriteLine(text);
+        }
+
+        return 0;
+    }
+}
