+using System.ComponentModel;
+using Spectre.Console;
+using Spectre.Console.Cli;
+
+namespace JobTrack.Cli;
+
+public enum TaskStatus
+{
+    Open,
+    InProgress,
+    InReview,
+    Done,
+    Blocked
+}
+
+public sealed class TaskListSettings : OutputSettings
+{
+    [CommandOption("--project <ID>")]
+    [Description("Filter by project id.")]
+    public string? ProjectId { get; set; }
+
+    [CommandOption("--status <STATUS>")]
+    [Description("Filter by task status.")]
+    public string? Status { get; set; }
+
+    public TaskStatus? ParsedStatus => Status is null
+        ? null
+        : TryParseStatus(Status, out var status)
+            ? status
+            : throw new InvalidOperationException(InvalidStatusMessage);
+
+    [CommandOption("--assignee <ASSIGNEE>")]
+    [Description("Filter by assignment.")]
+    public string? Assignee { get; set; }
+
+    [CommandOption("--priority <P>")]
+    [Description("Filter by priority.")]
+    public string? Priority { get; set; }
+
+    public override ValidationResult Validate()
+    {
+        var baseResult = base.Validate();
+        if (!baseResult.Successful)
+        {
+            return baseResult;
+        }
+
+        return TryParseStatus(Status, out _)
+            ? ValidationResult.Success()
+            : ValidationResult.Error(InvalidStatusMessage);
+    }
+
+    private static bool TryParseStatus(string? value, out TaskStatus status)
+    {
+        if (value is null)
+        {
+            status = default;
+            return true;
+        }
+
+        return EnumOptionParser.TryParseDefinedName(value, out status);
+    }
+
+    private static string InvalidStatusMessage =>
+        $"--status must be one of: {EnumOptionParser.AllowedNames<TaskStatus>()}.";
+}
+
+public sealed class TaskCommentsSettings : OutputSettings
+{
+    [CommandArgument(0, "<task-id>")]
+    [Description("The task id.")]
+    public string TaskId { get; set; } = string.Empty;
+}
+
+public sealed class TaskListCommand : JobTrackReadCommand<TaskListSettings>
+{
+    public TaskListCommand(IJobTrackApiClient client, IConsoleWriter console)
+        : base(client, console)
+    {
+    }
+
+    protected override Task<int> ExecuteAsync(
+        CommandContext context,
+        TaskListSettings settings,
+        CancellationToken cancellationToken)
+    {
+        var status = settings.ParsedStatus?.ToString();
+
+        return GetAndWriteAsync(
+            "task list",
+            (client, token) => client.ListTasksAsync(
+                settings.ProjectId,
+                status,
+                settings.Assignee,
+                settings.Priority,
+                token),
+            settings.OutputFormat,
+            cancellationToken);
+    }
+}
+
+public sealed class TaskCommentsCommand : JobTrackReadCommand<TaskCommentsSettings>
+{
+    public TaskCommentsCommand(IJobTrackApiClient client, IConsoleWriter console)
+        : base(client, console)
+    {
+    }
+
+    protected override Task<int> ExecuteAsync(
+        CommandContext context,
+        TaskCommentsSettings settings,
+        CancellationToken cancellationToken)
+    {
+        return GetAndWriteAsync(
+            "task comments",
+            (client, token) => client.ListTaskCommentsAsync(settings.TaskId, token),
+            settings.OutputFormat,
+            cancellationToken);
+    }
+}

