static async Task<int> WhoamiAsync()
{
    var (url, key) = ReadEnv();
    using var http = NewClient(url, key);
    using var resp = await http.GetAsync("/api/auth/me");
    var body = await resp.Content.ReadAsStringAsync();
    if (!resp.IsSuccessStatusCode)
    {
        Console.Error.WriteLine($"jt whoami: {(int)resp.StatusCode} {resp.ReasonPhrase}");
        Console.Error.WriteLine(body);
        return 1;
    }
    Console.WriteLine(Pretty(body));
    return 0;
}

static (string Url, string Key) ReadEnv()
{
    var url = Environment.GetEnvironmentVariable(ApiUrlEnv);
    var key = Environment.GetEnvironmentVariable(ApiKeyEnv);
    if (string.IsNullOrWhiteSpace(url))
        throw new InvalidOperationException($"{ApiUrlEnv} must be set (e.g. http://localhost:5000)");
    if (string.IsNullOrWhiteSpace(key))
        throw new InvalidOperationException($"{ApiKeyEnv} must be set");
    return (url.TrimEnd('/'), key);
}

static HttpClient NewClient(string baseUrl, string key)
{
    var http = new HttpClient { BaseAddress = new Uri(baseUrl) };
    http.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", key);
    http.DefaultRequestHeaders.UserAgent.ParseAdd("jt/0.1");
    return http;
}

static string Pretty(string raw)
{
    if (string.IsNullOrWhiteSpace(raw)) return raw;
    try
    {
        using var doc = JsonDocument.Parse(raw);
        return JsonSerializer.Serialize(doc.RootElement, new JsonSerializerOptions { WriteIndented = true });
    }
    catch
    {
        return raw;
    }
}

